const previous = $input.first().json;
if (previous.decision === 'BLOCKED' || previous.decision === 'DUPLICATE_REQUEST') {
  return [{ json: previous }];
}
const items = previous.items;
const issues = [];
const forbiddenPhrases = [
  'combine reviews', 'merge reviews', 'transfer reviews',
  'boost ranking', 'force merge', 'bypass amazon', 'manipulate reviews'
];
function scanForAbuse(value) {
  if (typeof value !== 'string') return null;
  const lower = value.toLowerCase();
  for (let i = 0; i < forbiddenPhrases.length; i++) {
    if (lower.includes(forbiddenPhrases[i])) {
      return forbiddenPhrases[i];
    }
  }
  return null;
}
let abuseFound = null;
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const fieldsToScan = ['brand', 'sku', 'asin'];
  for (let f = 0; f < fieldsToScan.length; f++) {
    const found = scanForAbuse(item[fieldsToScan[f]]);
    if (found) {
      abuseFound = found;
    }
  }
}
if (previous.request_text) {
  const found = scanForAbuse(previous.request_text);
  if (found) abuseFound = found;
}
if (abuseFound) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    issue_summary: 'This request was permanently blocked due to review manipulation language.',
    issues: [{
      issue_code: 'REVIEW_MANIPULATION_INTENT',
      severity: 'hard_block',
      message: 'This request has been permanently blocked because it contains language that suggests an intent to combine or transfer product reviews between listings. Amazon strictly prohibits any attempt to move, merge, or manipulate reviews. This block cannot be removed. If you believe this is a mistake, remove any mention of reviews from your request and resubmit. If the block persists, contact Amazon Seller Support directly.',
      question_to_user: null,
      example_answer: null,
      can_user_fix: false,
      can_user_override: false
    }],
    next_action: 'CANCEL_REQUEST',
    variation_structure: previous.variation_structure,
    items: previous.items,
    ptd_validation: previous.ptd_validation || null
  }}];
}
const nestedParentItems = items.filter(function(item) {
  return item.parentage === 'parent';
});
if (nestedParentItems.length > 0) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    issue_summary: 'One or more items are already parent listings and cannot be merged as children.',
    issues: nestedParentItems.map(function(item) {
      return {
        issue_code: 'NESTED_PARENT_STRUCTURE',
        severity: 'hard_block',
        asin: item.asin,
        sku: item.sku,
        field: 'parentage',
        message: item.sku + ' is already a parent listing. Amazon only supports one parent with direct children. You cannot create a parent of a parent.',
        question_to_user: null,
        example_answer: null,
        can_user_fix: false,
        can_user_override: false
      };
    }),
    next_action: 'CANCEL_REQUEST',
    variation_structure: previous.variation_structure,
    items: previous.items,
    ptd_validation: previous.ptd_validation || null
  }}];
}
if (previous.simulate_missing_value === true) {
  issues.push({
    issue_code: 'MISSING_VARIATION_VALUE',
    severity: 'fixable',
    asin: items[0].asin,
    sku: items[0].sku,
    field: 'variation_value',
    message: items[0].sku + ' is missing its variation value.',
    question_to_user: 'Please enter the color or size for ' + items[0].sku + '.',
    example_answer: 'Red',
    can_user_fix: true,
    can_user_override: false
  });
}
if (issues.length > 0) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'NEEDS_INPUT',
    issue_summary: issues.length + ' issue(s) need your input before continuing.',
    issues: issues,
    next_action: 'USER_CLARIFICATION_REQUIRED',
    variation_structure: previous.variation_structure,
    sizes: previous.sizes,
    colors: previous.colors,
    matrix_assignments: previous.matrix_assignments || null,
    items: previous.items,
    ptd_validation: previous.ptd_validation || null
  }}];
}
return [{ json: {
  request_id: previous.request_id,
  decision: 'CAN_CONTINUE_TO_DRY_RUN',
  issue_summary: 'No issues found.',
  issues: [],
  next_action: 'PROCEED',
  variation_structure: previous.variation_structure,
  sizes: previous.sizes,
  colors: previous.colors,
  matrix_assignments: previous.matrix_assignments || null,
  items: previous.items,
  ptd_validation: previous.ptd_validation || null
}}];

const previous = $input.first().json;

if (previous.decision === 'BLOCKED') {
  return [{ json: previous }];
}

const AMAZON_TIP = 'Use clear Amazon-friendly values such as Red, Green, Yellow, XL, Medium, Light, Dark.';
const ptdWarnings = (previous.ptd_validation && previous.ptd_validation.warnings) || [];

function normalizeVariationValue(value) {
  const trimmed = String(value ?? '').trim();
  const lower = trimmed.toLowerCase();

if (lower === 'extra large' || lower === 'extra-large') {
    return { trimmed, has_formatting_issue: true, suggestion: 'XL',
      question_to_user: 'Your size value "' + trimmed + '" is not in Amazon\'s standard format. Amazon uses "XL" for extra large. Should we use "XL"?',
      issue_code: 'NON_STANDARD_SIZE',
      message: 'The size value for this SKU is not in Amazon\'s standard format. Amazon requires abbreviated size names like XL, XXL, S, M, L — not spelled-out versions like "extra large". Please confirm the correct format before continuing.' };
  }
  if (lower === 'extra small' || lower === 'extra-small') {
    return { trimmed, has_formatting_issue: true, suggestion: 'XS',
      question_to_user: 'Your size value "' + trimmed + '" is not in Amazon\'s standard format. Amazon uses "XS" for extra small. Should we use "XS"?',
      issue_code: 'NON_STANDARD_SIZE',
      message: 'The size value for this SKU is not in Amazon\'s standard format. Amazon requires abbreviated size names like XL, XXL, S, M, L — not spelled-out versions like "extra small". Please confirm the correct format before continuing.' };
  }
 if (lower === 'double extra large') {
    return { trimmed, has_formatting_issue: true, suggestion: 'XXL',
      question_to_user: 'Your size value "' + trimmed + '" is not in Amazon\'s standard format. Amazon uses "XXL" for double extra large. Should we use "XXL"?',
      issue_code: 'NON_STANDARD_SIZE' };
  }
  if (trimmed.includes('-')) {
    const suggestion = trimmed.replace(/-/g, ' ');
    return { trimmed, has_formatting_issue: true, suggestion: suggestion,
      question_to_user: 'Your variation value "' + trimmed + '" contains a hyphen. Amazon typically uses spaces instead (e.g., "' + suggestion + '"). Should we use "' + suggestion + '"?',
      issue_code: 'HYPHEN_IN_VALUE',
      message: 'The variation value for this SKU contains a hyphen character. Amazon listing values use spaces, not hyphens. For example, "Dark-Red" should be "Dark Red". Please confirm the correct value before continuing.' };
  }
 if (trimmed.includes('_')) {
    const suggestion = trimmed.replace(/_/g, ' ');
    return { trimmed, has_formatting_issue: true, suggestion: suggestion,
      question_to_user: 'Your variation value "' + trimmed + '" contains an underscore. Amazon typically uses spaces instead (e.g., "' + suggestion + '"). Should we use "' + suggestion + '"?',
      issue_code: 'UNDERSCORE_IN_VALUE',
      message: 'The variation value for this SKU contains an underscore character. Amazon listing values use spaces, not underscores. For example, "Dark_Red" should be "Dark Red". Please confirm the correct value before continuing.' };
  }
  return { trimmed, has_formatting_issue: false, suggestion: null,
    question_to_user: null, issue_code: null };
}

const items = previous.items;
const issues = [];
const seenValues = {};

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  if (!item.variation_value || String(item.variation_value).trim() === '') {
    issues.push({
      issue_code: 'MISSING_VARIATION_VALUE',
      severity: 'fixable',
      asin: item.asin,
      sku: item.sku,
      field: 'variation_value',
      message: item.sku + ' is missing its variation value.',
      question_to_user: 'Please enter the color or size for ' + item.sku + '.',
      example_answer: 'Red',
      can_user_fix: true,
      can_user_override: false
    });
    continue;
  }

  const norm = normalizeVariationValue(item.variation_value);

 if (norm.has_formatting_issue) {
    issues.push({
      issue_code: norm.issue_code,
      severity: 'fixable',
      asin: item.asin,
      sku: item.sku,
      field: 'variation_value',
      current_value: norm.trimmed,
      suggested_value: norm.suggestion,
      message: norm.message || 'Formatting issue detected on ' + item.sku + '.',
      question_to_user: norm.question_to_user,
      example_answer: norm.suggestion,
      can_user_fix: true,
      can_user_override: false
    });
    continue;
  }

  const key = norm.trimmed.toLowerCase();
  if (seenValues[key]) {
    issues.push({
      issue_code: 'DUPLICATE_VARIATION_VALUE',
      severity: 'hard_block',
      asin: item.asin,
      sku: item.sku,
      field: 'variation_value',
      duplicate_of_sku: seenValues[key],
      message: item.sku + ' has the same variation value as ' + seenValues[key] + ' (' + norm.trimmed + ').',
      question_to_user: null,
      can_user_fix: false,
      can_user_override: false
    });
  } else {
    seenValues[key] = item.sku;
  }
}

const hasHardBlock = issues.some(function(iss) {
  return iss.severity === 'hard_block';
});

if (hasHardBlock) {
  return [{
    json: {
      request_id: previous.request_id,
      decision: 'BLOCKED',
      variation_theme: previous.variation_structure,
      tip: AMAZON_TIP,
      issue_summary: 'One or more hard blocks prevent this merge.',
      issues: issues,
      warnings: ptdWarnings,
      next_action: 'CANCEL_OR_FIX_DATA'
    }
  }];
}

if (issues.length > 0) {
  return [{
    json: {
      request_id: previous.request_id,
      decision: 'NEEDS_INPUT',
      variation_theme: previous.variation_structure,
      tip: AMAZON_TIP,
      issue_summary: issues.length + ' issue(s) need your input before continuing.',
      issues: issues,
      warnings: ptdWarnings,
      next_action: 'USER_CLARIFICATION_REQUIRED'
    }
  }];
}

return [{
  json: {
    request_id: previous.request_id,
    decision: 'CAN_CONTINUE_TO_DRY_RUN',
    variation_theme: previous.variation_structure,
    tip: AMAZON_TIP,
    issue_summary: 'All variation values are valid.',
    issues: [],
    warnings: ptdWarnings,
    validated_items: items,
    next_action: 'PROCEED'
  }
}];

// Paste this into a new Code node after the "Not Sure" output
const previous = $input.first().json;
return [{
  json: {
    request_id: previous.request_id,
    decision: 'NEEDS_INPUT',
    routed_to: 'theme_suggestion_pending',
    message: 'Theme suggestion requires real Amazon schema data, available starting Week 6. For now, please choose single_theme or double_theme explicitly.',
    items: previous.items
  }
}];

const body = $input.first().json.body;
const errors = [];

const requiredFields = ['request_id', 'marketplace_id', 'seller_id', 'variation_structure'];
for (const field of requiredFields) {
  if (!body[field]) {
    errors.push({
      field: field,
      reason: 'MISSING_REQUIRED_FIELD',
      message: 'Missing required field: ' + field + '. All required fields are: request_id, marketplace_id, seller_id, variation_structure, items (minimum 2).'
    });
  }
}

const validStructures = ['single_theme', 'double_theme', 'not_sure'];
if (body.variation_structure && !validStructures.includes(body.variation_structure)) {
  errors.push({
    field: 'variation_structure',
    reason: 'INVALID_VALUE',
    message: 'variation_structure must be one of: single_theme, double_theme, or not_sure.'
  });
}

if (body.auto_execute === true) {
  errors.push({
    field: 'auto_execute',
    reason: 'AUTO_EXECUTE_NOT_ALLOWED',
    message: 'Automatic execution is not allowed. This app requires human review and approval before any changes are submitted to Amazon. Please set auto_execute to false and resubmit. You will be asked to review and approve the changes before anything is sent to Amazon.'
  });
}

if (!Array.isArray(body.items)) {
  errors.push({
    field: 'items',
    reason: 'MISSING_REQUIRED_FIELD',
    message: 'Missing required field: items. Please provide an array of at least 2 products to merge.'
  });
} else {
  if (body.items.length < 2) {
    errors.push({
      field: 'items',
      reason: 'MINIMUM_ITEMS_REQUIRED',
      message: 'A variation merge requires at least 2 products. You have submitted only ' + body.items.length + '. Please add at least one more product — variations need a minimum of 2 and a maximum of 10 items.'
    });
  }
  if (body.items.length > 10) {
    errors.push({
      field: 'items',
      reason: 'MAXIMUM_ITEMS_EXCEEDED',
      message: 'You have submitted ' + body.items.length + ' products. The maximum allowed is 10. Please reduce your selection to 10 or fewer items and resubmit.'
    });
  }
  body.items.forEach(function(item, index) {
    ['asin', 'sku', 'brand'].forEach(function(key) {
      if (!item[key]) {
        errors.push({
          field: 'items[' + index + '].' + key,
          reason: 'MISSING_REQUIRED_FIELD',
          message: 'Item at position ' + (index + 1) + ' is missing required field: ' + key + '. Every item must have an asin, sku, and brand.'
        });
      }
    });
  });
}

if (errors.length > 0) {
  const firstError = errors[0];
  return [{
    json: {
      request_id: body.request_id || null,
      decision: 'BLOCKED',
      errors: errors,
      message: firstError.message
    }
  }];
}

return [{
  json: {
    request_id: body.request_id,
    decision: 'VALID_INPUT',
    message: 'Input passed all required field checks.',
    data: body
  }
}];

const previous = $input.first().json;

if (previous.decision === 'BLOCKED' || previous.decision === 'NEEDS_INPUT') {
  return [{ json: previous }];
}

const sizes = previous.sizes || (previous.data ? previous.data.sizes : null);
const colors = previous.colors || (previous.data ? previous.data.colors : null);

if (!Array.isArray(sizes) || sizes.length === 0) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    reason: 'MISSING_SIZES_ARRAY',
    message: 'sizes array is missing or empty. Required for double_theme.',
    variation_structure: previous.variation_structure
  }}];
}

if (!Array.isArray(colors) || colors.length === 0) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    reason: 'MISSING_COLORS_ARRAY',
    message: 'colors array is missing or empty. Required for double_theme.',
    variation_structure: previous.variation_structure
  }}];
}

const matrix = [];
let cellIndex = 0;

for (let r = 0; r < sizes.length; r++) {
  const row = [];
  for (let c = 0; c < colors.length; c++) {
    cellIndex++;
    row.push({
      cell_id: 'CELL-' + cellIndex,
      size: sizes[r],
      color: colors[c],
      sku: null,
      asin: null,
      status: 'empty'
    });
  }
  matrix.push(row);
}

const totalCells = sizes.length * colors.length;

return [{ json: {
  request_id: previous.request_id,
  decision: 'MATRIX_READY',
  variation_structure: previous.variation_structure,
  sizes: sizes,
  colors: colors,
  matrix: matrix,
  matrix_summary: {
    total_cells: totalCells,
    filled_cells: 0,
    empty_cells: totalCells

  },
     matrix_assignments: previous.matrix_assignments || null, 
  items: previous.items
}}];

const previous = $input.first().json;
if (previous.decision === 'BLOCKED') {
  return [{ json: previous }];
}
const matrix = previous.matrix;
const assignments = previous.matrix_assignments ||
  (previous.data ? previous.data.matrix_assignments : null);
// If no assignments sent yet, return the empty matrix as-is
if (!Array.isArray(assignments) || assignments.length === 0) {
  return [{ json: previous }];
}
// Check for duplicate SKUs across all assignments
const skuCount = {};
for (let i = 0; i < assignments.length; i++) {
  const sku = assignments[i].sku;
  if (!sku) continue;
  skuCount[sku] = (skuCount[sku] || 0) + 1;
}
const duplicateSkus = Object.keys(skuCount).filter(function(s) {
  return skuCount[s] > 1;
});
if (duplicateSkus.length > 0) {
  const dupMessage = 'The following SKU(s) have been assigned to more than one cell: ' + duplicateSkus.join(', ') + '. Each SKU can only appear once in the matrix.';
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    reason: 'DUPLICATE_MATRIX_ASSIGNMENT',
    issue_summary: 'One or more SKUs are assigned to multiple matrix cells.',
    message: dupMessage,
    duplicate_skus: duplicateSkus,
    issues: [{
      issue_code: 'DUPLICATE_MATRIX_ASSIGNMENT',
      severity: 'hard_block',
      message: dupMessage,
      duplicate_skus: duplicateSkus,
      can_user_fix: false,
      can_user_override: false
    }],
    next_action: 'CANCEL_REQUEST',
    variation_structure: previous.variation_structure,
    matrix: previous.matrix,
    items: previous.items
  }}];
}
// Build lookup: cell_id → assignment
const assignmentMap = {};
for (let i = 0; i < assignments.length; i++) {
  assignmentMap[assignments[i].cell_id] = assignments[i];
}
// Merge assignments into the matrix
const updatedMatrix = [];
let filledCount = 0;
for (let r = 0; r < matrix.length; r++) {
  const updatedRow = [];
  for (let c = 0; c < matrix[r].length; c++) {
    const cell = matrix[r][c];
    const match = assignmentMap[cell.cell_id];
    if (match) {
      updatedRow.push({
        cell_id: cell.cell_id,
        size: cell.size,
        color: cell.color,
        sku: match.sku,
        asin: match.asin || null,
        status: 'filled'
      });
      filledCount++;
    } else {
      updatedRow.push(cell);
    }
  }
  updatedMatrix.push(updatedRow);
}
const totalCells = previous.matrix_summary.total_cells;
const emptyCount = totalCells - filledCount;
// All done — Matrix Validator handles empty cell checks
return [{ json: {
  request_id: previous.request_id,
  decision: 'ASSIGNMENT_COMPLETE',
  variation_structure: previous.variation_structure,
  sizes: previous.sizes,
  colors: previous.colors,
  matrix: updatedMatrix,
  matrix_assignments: previous.matrix_assignments || null,
  matrix_summary: {
    total_cells: totalCells,
    filled_cells: filledCount,
    empty_cells: emptyCount
  },
  items: previous.items
}}];

const previous = $input.first().json;

if (previous.decision === 'BLOCKED') {
  return [{ json: previous }];
}
if (previous.decision === 'NEEDS_INPUT') {
  return [{ json: previous }];
}

// Pass NEEDS_CONFIRMATION straight through — seller hasn't confirmed yet
if (previous.decision === 'NEEDS_CONFIRMATION') {
  return [{ json: previous }];
}

const matrix = previous.matrix;
const items = previous.items;
const issues = [];

// Build a set of parent SKUs from the items array
const parentSkus = {};
for (let i = 0; i < items.length; i++) {
  if (items[i].parentage === 'parent') {
    parentSkus[items[i].sku] = true;
  }
}

// Flatten matrix into a single array of cells for easier iteration
const allCells = [];
for (let r = 0; r < matrix.length; r++) {
  for (let c = 0; c < matrix[r].length; c++) {
    allCells.push(matrix[r][c]);
  }
}

// Check 1 — Duplicate size+color combination
const comboSeen = {};
for (let i = 0; i < allCells.length; i++) {
  const cell = allCells[i];
  if (cell.status !== 'filled') continue;
  const comboKey = cell.size + '|' + cell.color;
  if (comboSeen[comboKey]) {
    issues.push({
      issue_code: 'DUPLICATE_MATRIX_COMBINATION',
      severity: 'hard_block',
      cell_id: cell.cell_id,
      size: cell.size,
      color: cell.color,
      sku: cell.sku,
      message: 'Two SKUs share the same variation combination ' + cell.size + '/' + cell.color + '. Each size+color combination must be unique.',
      question_to_user: null,
      can_user_fix: false,
      can_user_override: false
    });
  }
  comboSeen[comboKey] = true;
}

// Check 2 — Nested parent structure
for (let i = 0; i < allCells.length; i++) {
  const cell = allCells[i];
  if (cell.status !== 'filled') continue;
  if (parentSkus[cell.sku]) {
    issues.push({
      issue_code: 'NESTED_PARENT_STRUCTURE',
      severity: 'hard_block',
      cell_id: cell.cell_id,
      size: cell.size,
      color: cell.color,
      sku: cell.sku,
      message: cell.sku + ' is already a parent SKU and cannot be assigned as a child. Amazon only supports one parent with direct children — never a parent of a parent.',
      question_to_user: null,
      can_user_fix: false,
      can_user_override: false
    });
  }
}

// Check 3 — Missing cells (still empty after assignment)
for (let i = 0; i < allCells.length; i++) {
  const cell = allCells[i];
  if (cell.status === 'empty') {
    issues.push({
      issue_code: 'MISSING_MATRIX_CELL',
      severity: 'fixable',
      cell_id: cell.cell_id,
      size: cell.size,
      color: cell.color,
      sku: null,
      message: 'No SKU has been assigned to the ' + cell.size + '/' + cell.color + ' cell.',
      question_to_user: 'Is the ' + cell.size + '/' + cell.color + ' combination intentionally missing from your variation family? Yes / No',
      can_user_fix: true,
      can_user_override: false
    });
  }
}

// Hard blocks take priority — return immediately if any exist
const hardBlocks = issues.filter(function(i) {
  return i.severity === 'hard_block';
});

if (hardBlocks.length > 0) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    reason: hardBlocks[0].issue_code,
    issue_summary: hardBlocks.length + ' hard block(s) found. This matrix cannot be submitted.',
    issue_diagnosis: hardBlocks,
    variation_structure: previous.variation_structure,
    sizes: previous.sizes,
    colors: previous.colors,
    matrix: previous.matrix,
    matrix_summary: previous.matrix_summary,
    items: previous.items,
    next_action: 'CANCEL_OR_FIX_DATA'
  }}];
}

// Fixable issues — ask questions before continuing
if (issues.length > 0) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'NEEDS_INPUT',
    reason: 'MISSING_MATRIX_CELL',
    issue_summary: issues.length + ' issue(s) need your input before continuing.',
    issue_diagnosis: issues,
    variation_structure: previous.variation_structure,
    sizes: previous.sizes,
    colors: previous.colors,
    matrix: previous.matrix,
    matrix_summary: previous.matrix_summary,
    items: previous.items,
    next_action: 'USER_CLARIFICATION_REQUIRED'
  }}];
}

// All checks passed
return [{ json: {
  request_id: previous.request_id,
  decision: 'MATRIX_VALID',
  issue_summary: 'All matrix checks passed. Ready to continue.',
  issue_diagnosis: [],
  variation_structure: previous.variation_structure,
  sizes: previous.sizes,
  colors: previous.colors,
  matrix: previous.matrix,
  matrix_summary: previous.matrix_summary,
  items: previous.items,
  next_action: 'PROCEED'
}}];

const prev = $input.first().json;

if (prev.decision === 'DUPLICATE_REQUEST') {
  return [{ json: prev }];
}

const supabaseResult = $input.first().json;
const originalData = $('Input Validator').first().json;
return [{ json: { ...originalData, supabase_log: { status: 'ok', inserted_id: supabaseResult[0]?.id || supabaseResult?.id } } }];

const previous = $input.first().json;
if (previous.decision === 'BLOCKED' || previous.decision === 'DUPLICATE_REQUEST') { 
  return [{ json: previous }]; 
}
if (previous.decision === 'BLOCKED') {
  return [{ json: previous }];
}
const items = previous.items || [];
const requestId = previous.request_id;
return items.map(function(item) {
  return {
    json: {
      _original_payload: previous,
      request_id: requestId,
      asin: item.asin,
      sku: item.sku,
      variation_value: item.variation_value || null,
      normalized_brand: item.normalized_brand,
      normalized_product_type: item.product_type || null,
