}
const items = original.data.items;
const firstBrand = catalogData.brand || items[0].brand;
const normalized_brand = catalogData.normalized_brand || firstBrand.toLowerCase().trim();
const enrichedItems = items.map(function(item) {
  const itemBrand = item.brand || firstBrand;
  return {
    asin: item.asin,
    sku: item.sku,
    brand: itemBrand,
