const variationStructure = prev.variation_structure;
const requiredChildAttributes = prev.required_child_attributes || [];
const warnings = [];

// Real theme data now comes from wf15's live cache (hit) or wf15's live SP-API
// fetch (miss) -- both converge here with the same shape. No hardcoded theme
