  return [{ json: {
    request_id: prev.request_id,
    decision: 'BLOCKED',
    reason: 'NO_THEME_DATA_AVAILABLE',
    message: msg,
    issue_summary: 'Unable to validate variation theme -- no schema data available.',
    issues: [{
      issue_code: 'NO_THEME_DATA_AVAILABLE',
      severity: 'hard_block',
      message: msg,
      can_user_fix: false,
      can_user_override: false
    }],
    next_action: 'CANCEL_REQUEST',
    variation_structure: variationStructure,
