function dimensionCount(themeName) {
  return themeName.split('/').length;
}
function findRealTheme(list, dimensions) {
  return list.find(function(t) { return dimensionCount(t) === dimensions; });
}

if (variationStructure === 'not_sure') {
  const singleOptions = validThemes.filter(function(t) { return dimensionCount(t) === 1; });
  const doubleOptions = validThemes.filter(function(t) { return dimensionCount(t) === 2; });
  return [{ json: {
    request_id: prev.request_id,
    decision: 'NEEDS_INPUT',
    reason: 'THEME_SELECTION_REQUIRED',
    message: 'Here are the real variation themes Amazon supports for this product type. Pick single_theme or double_theme and resubmit.',
