    available_single_themes: singleOptions,
    available_double_themes: doubleOptions,
    deprecated_themes: deprecatedThemes,
    next_action: 'USER_CLARIFICATION_REQUIRED',
    variation_structure: variationStructure,
    items: prev.items
  }}];
}

const wantedDimensions = variationStructure === 'double_theme' ? 2 : 1;
const matchedTheme = findRealTheme(validThemes, wantedDimensions);

if (!matchedTheme) {
  const deprecatedMatch = findRealTheme(deprecatedThemes, wantedDimensions);
  const structureLabel = wantedDimensions === 2 ? 'two-attribute (double)' : 'single-attribute';
  const message = deprecatedMatch
    ? 'The variation theme that would match your selection ("' + deprecatedMatch + '") has been retired by Amazon for this product type and can no longer be used. Currently supported themes are: ' + validThemes.join(', ') + '.'
    : 'Amazon does not support a ' + structureLabel + ' variation theme for this product type. Supported themes are: ' + validThemes.join(', ') + '.';
  const issueCode = deprecatedMatch ? 'DEPRECATED_VARIATION_THEME' : 'UNSUPPORTED_VARIATION_THEME';
  return [{ json: {
    request_id: prev.request_id,
    decision: 'BLOCKED',
    reason: issueCode,
    message: message,
    issue_summary: 'Unsupported variation theme.',
    issues: [{
      issue_code: issueCode,
      severity: 'hard_block',
      message: message,
      can_user_fix: false,
      can_user_override: false
    }],
    next_action: 'CANCEL_REQUEST',
    variation_structure: variationStructure,
    supported_themes: validThemes,
    items: prev.items
  }}];
}

const themeParts = matchedTheme.split('/');
const dimension1Theme = themeParts[0];
const dimension1Attribute = themeParts[0].toLowerCase();
const dimension2Theme = themeParts[1] || null;
const dimension2Attribute = themeParts[1] ? themeParts[1].toLowerCase() : null;

// FIX-06 (carried forward from the earlier version): warn when the chosen theme's
// attribute is on Amazon's required-child-attributes list but this item doesn't
// have a value for it yet. Now checks the actual matched attribute directly instead
// of guessing via a fixed "which attributes count as theme attributes" list.
if (variationStructure === 'single_theme' && requiredChildAttributes.includes(dimension1Attribute)) {
  prev.items.forEach(function(item) {
    const hasValue = !!(item.variation_value && String(item.variation_value).trim() !== '');
    if (!hasValue) {
      warnings.push({
        issue_code: 'MISSING_REQUIRED_CHILD_ATTRIBUTE',
        severity: 'warning',
        attribute: dimension1Attribute,
        sku: item.sku,
        message: dimension1Attribute + ' is required by Amazon for ' + item.normalized_product_type + ' variations but is not present on ' + item.sku + '.',
        can_user_fix: true
      });
    }
  });
}

const updatedItems = prev.items.map(function(item) {
  return {
    ...item,
    matched_theme: matchedTheme,
    theme_attribute_status: 'verified'
  };
});

return [{ json: {
  ...prev,
  items: updatedItems,
  ptd_validation: {
    status: 'passed',
    matched_theme: matchedTheme,
    dimension1_theme: dimension1Theme,
    dimension1_attribute: dimension1Attribute,
    dimension2_theme: dimension2Theme,
    dimension2_attribute: dimension2Attribute,
    supported_themes: validThemes,
    deprecated_themes: deprecatedThemes,
    warnings: warnings
  }
}}];

const prev = $('WF01 Single Theme Logger Prep').first().json;
const issues = prev.issues || [];
const firstIssue = issues[0] || {};
const warnings = prev._original_payload?.warnings || prev.warnings || [];

const issuesSummary = issues.length > 0
  ? issues.map(function(i) { return i.issue_code + ' (' + i.message + ')'; }).join(' | ')
  : 'none';

const warningsSummary = warnings.length > 0
  ? warnings.length + ' warning(s) - ' + warnings.map(function(w) { return w.attribute + ' missing on ' + w.sku; }).join('; ')
  : 'none';

const aiMessage = 'Explain this validation result. Decision: ' + prev.decision +
  '. Total issues: ' + issues.length +
  '. Issues: ' + issuesSummary +
  '. Warnings: ' + warningsSummary + '.';

return [{ json: {
