  request_id: prev.request_id,
  decision: prev.decision,
  issue_summary: prev.issue_summary || 'No issues found.',
  issues: issues,
  warnings: warnings,
  variation_structure: prev.variation_structure,
  items: prev.items || [],
  ai_message: aiMessage
}}];

