}

const issues = [];

for (let i = 0; i < sizes.length; i++) {
  const norm = normalizeVariationValue(sizes[i]);
  if (norm.has_formatting_issue) {
    issues.push({
      issue_code: norm.issue_code,
      severity: 'fixable',
      dimension: 'size',
      value: norm.trimmed,
      suggested_value: norm.suggestion,
      message: norm.message || 'Formatting issue detected on size value "' + norm.trimmed + '".',
      question_to_user: norm.question_to_user,
      example_answer: norm.suggestion,
      can_user_fix: true,
      can_user_override: false
